async function editJadwal(a,n,t,s){$("#editJadwalLabel").text(a),$("#sectionjnsDns option[value='"+s+"']").prop("selected",!0),$("#tgl").val(t),$("#sectionjnsDns").val(s),$("#nik").val(n),$("#editJadwal").modal("show")}async function saveJadwal(){let a=$("#nik").val(),n=$("#tgl").val(),t=$("#sectionjnsDns").val(),s={nik:a,typeDns:t,date:n};console.log(s),$.ajax({url:"/api/presensi/anggota",method:"POST",data:s,success:function(e){getTabel($("#periode").val()),Swal.fire(e.message,"data berhasil diubah","success")},error:function(e){Swal.fire(e.responseJSON.message,e.responseJSON.data,"error")}})}const Toast=Swal.mixin({toast:!0,position:"top-end",showConfirmButton:!1,timer:2e3,timerProgressBar:!0,didOpen:a=>{a.onmouseenter=Swal.stopTimer,a.onmouseleave=Swal.resumeTimer}});async function updrateJadwal(a,n,t){let s={nik:a,typeDns:t,date:n};$.ajax({url:"/api/presensi/anggota",method:"POST",data:s,success:function(e){Toast.fire({icon:"success",title:e.message})},error:function(e){Swal.fire(e.responseJSON.message,e.responseJSON.data,"error"),getTabel($("#periode").val())}})}
